                    continue

                a1_a, a1_b = candidate_bonds[b_idx_1]
                a2_c, a2_d = candidate_bonds[b_idx_2]

                atoms_involved = {a1_a, a1_b, a2_c, a2_d}
                if len(atoms_involved) != 4: 
