                    continue

                rw_mol = Chem.RWMol(m)
                try:
                    rw_mol.RemoveBond(a1_a, a1_b)
                    rw_mol.RemoveBond(a2_c, a2_d)

                    # Add A-D and C-B (using indices from original m)
                    rw_mol.AddBond(a2_d, a1_a, Chem.BondType.SINGLE) 
                    rw_mol.AddBond(a2_c, a1_b, Chem.BondType.SINGLE) 
                except Exception as e:
                    attempts_per_mol -= 1
                    continue

                new = rw_mol.GetMol()

                try:
                    Chem.SanitizeMol(new)
                except Exception as e:
                    attempts_per_mol -= 1
                    continue

                frags = Chem.GetMolFrags(new, asMols=False)
                if len(frags) != 1: 
                    attempts_per_mol -= 1
                    continue

                new_smi = Chem.MolToSmiles(new, canonical=True)

                orig_smi_canonical = Chem.MolToSmiles(m, canonical=True) 

                if new_smi == orig_smi_canonical:
                    attempts_per_mol -= 1
                    continue

                valid_pairs.append((smi, new))
                kept_count += 1

        except Exception as e:
            pass

    return valid_pairs[:300]

